        } else if (typeof args?.avatarPath === 'string' && args.avatarPath !== '') {
          avatar = { kind: 'file', path: args.avatarPath, label: args.avatarPath };
        } else if (typeof args?.avatarFromAssets === 'string' && args.avatarFromAssets !== '') {
